import numpy as np

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    """Best fit with a bonus for near-perfect fits (small leftover gaps)."""
    r = bins - item  # leftover space after placing the item
    # Linear penalty on leftover (best fit) plus a sharp bonus for almost-exact fits.
    return -r + 0.5 * np.exp(-r / 0.05)

